450: OrphanablePtr<LoadBalancingPolicy> XdsOverrideHostLb::CreateChildPolicyLocked(
451:     const ChannelArgs& args) {
452:   LoadBalancingPolicy::Args lb_policy_args;
453:   lb_policy_args.work_serializer = work_serializer();
454:   lb_policy_args.args = args;
455:   lb_policy_args.channel_control_helper =
456:       std::make_unique<Helper>(Ref(DEBUG_LOCATION, "Helper"));
457:   OrphanablePtr<LoadBalancingPolicy> lb_policy =
458:       MakeOrphanable<ChildPolicyHandler>(std::move(lb_policy_args),
459:                                          &grpc_lb_xds_override_host_trace);
460:   if (GRPC_TRACE_FLAG_ENABLED(grpc_lb_xds_override_host_trace)) {
461:     gpr_log(GPR_INFO,
462:             "[xds_override_host_lb %p] Created new child policy handler %p",
463:             this, lb_policy.get());
464:   }
465:   // Add our interested_parties pollset_set to that of the newly created
466:   // child policy. This will make the child policy progress upon activity on
467:   // this policy, which in turn is tied to the application's call.
468:   grpc_pollset_set_add_pollset_set(lb_policy->interested_parties(),
469:                                    interested_parties());
470:   return lb_policy;
471: }
