473: absl::StatusOr<ServerAddressList> XdsOverrideHostLb::UpdateAddressMap(
474:     absl::StatusOr<ServerAddressList> addresses,
475:     int override_host_status_mask) {
476:   // It will also retain subchannels until after update. Otherwise destroying
477:   // the subchannels will try to reacquire the locks in the ResetSubchannel...
478:   std::map<std::string, SubchannelEntry, std::less<>> new_map;
479:   absl::StatusOr<ServerAddressList> child_addresses;
480:   {
481:     MutexLock lock(&subchannel_map_mu_);
482:     if (addresses.ok()) {
483:       child_addresses.emplace();
484:       for (const auto& address : *addresses) {
485:         auto status = GetAddressHealthStatus(address);
486:         bool draining = false;
487:         if (status.status() != XdsHealthStatus::HealthStatus::kDraining) {
488:           child_addresses->push_back(address);
489:         } else if ((override_host_status_mask & HealthStatusBitMask(status)) ==
490:                    0) {
491:           continue;
492:         } else {
493:           draining = true;
494:         }
495:         auto key = grpc_sockaddr_to_string(&address.address(), false);
496:         if (key.ok()) {
497:           auto it = subchannel_map_.find(*key);
498:           if (it == subchannel_map_.end()) {
499:             new_map.emplace(std::make_pair(*key, SubchannelEntry(nullptr)));
500:           } else {
501:             SubchannelWrapper* subchannel = it->second.GetSubchannel();
502:             if (subchannel != nullptr && draining) {
503:               new_map.emplace(
504:                   std::make_pair(*key, SubchannelEntry(subchannel->Ref())));
505:             } else {
506:               new_map.emplace(
507:                   std::make_pair(*key, SubchannelEntry(subchannel)));
508:             }
509:           }
510:         }

720:                                            const JsonArgs& args,
721:                                            ValidationErrors* errors) {
722:   {
723:     ValidationErrors::ScopedField field(errors, ".childPolicy");
724:     auto it = json.object_value().find("childPolicy");
725:     if (it == json.object_value().end()) {
726:       errors->AddError("field not present");
727:     } else {
728:       auto child_policy_config = CoreConfiguration::Get()
729:                                      .lb_policy_registry()
730:                                      .ParseLoadBalancingConfig(it->second);
731:       if (!child_policy_config.ok()) {
732:         errors->AddError(child_policy_config.status().message());
733:       } else {
734:         child_config_ = std::move(*child_policy_config);
735:       }
736:     }
737:   }
738:   {
739:     ValidationErrors::ScopedField field(errors, ".overrideHostStatus");
740:     auto host_status_list = LoadJsonObjectField<std::vector<std::string>>(
741:         json.object_value(), args, "overrideHostStatus", errors,
742:         /*required=*/false);
743:     if (host_status_list.has_value()) {
744:       override_host_status_mask_ = 0;
745:       for (size_t i = 0; i < host_status_list->size(); ++i) {
746:         const std::string& host_status = (*host_status_list)[i];
747:         auto status = XdsHealthStatus::FromString(host_status);
748:         if (!status.has_value()) {
749:           ValidationErrors::ScopedField field(errors,
750:                                               absl::StrCat("[", i, "]"));
751:           errors->AddError("invalid host status");
752:         } else {
753:           override_host_status_mask_ |= HealthStatusBitMask(*status);
754:         }
755:       }
756:     }
757:   }
758: }
